
SELECT 'core.order_items' AS table_name, 'quantity <= 0' AS validation_check, COUNT(*) AS invalid_rows FROM core.order_items WHERE quantity IS NOT NULL AND quantity <= 0 UNION ALL SELECT 'core.order_items', 'product_price < 0', COUNT(*) FROM core.order_items WHERE product_price < 0 UNION ALL SELECT 'core.order_items', 'discount < 0', COUNT(*) FROM core.order_items WHERE discount < 0 UNION ALL SELECT 'core.order_items', 'discount_rate < 0', COUNT(*) FROM core.order_items WHERE discount_rate < 0 UNION ALL SELECT 'core.order_items', 'sales < 0', COUNT(*) FROM core.order_items WHERE sales < 0 UNION ALL SELECT 'core.order_items', 'order_item_total < 0', COUNT(*) FROM core.order_items WHERE order_item_total < 0 UNION ALL SELECT 'core.orders', 'days_for_shipping_real < 0', COUNT(*) FROM core.orders WHERE days_for_shipping_real < 0 UNION ALL SELECT 'core.orders', 'days_for_shipment_scheduled < 0', COUNT(*) FROM core.orders WHERE days_for_shipment_scheduled < 0 UNION ALL SELECT 'core.orders', 'late_delivery_risk NOT IN (0,1)', COUNT(*) FROM core.orders WHERE late_delivery_risk IS NOT NULL AND late_delivery_risk NOT IN (0,1) UNION ALL SELECT 'core.products', 'product_price < 0', COUNT(*) FROM core.products WHERE product_price < 0 UNION ALL SELECT 'analytics.fact_order_items', 'quantity <= 0', COUNT(*) FROM analytics.fact_order_items WHERE quantity IS NOT NULL AND quantity <= 0 UNION ALL SELECT 'analytics.fact_order_items', 'sales < 0', COUNT(*) FROM analytics.fact_order_items WHERE sales < 0 UNION ALL SELECT 'analytics.fact_order_items', 'discount < 0', COUNT(*) FROM analytics.fact_order_items WHERE discount < 0 UNION ALL SELECT 'analytics.fact_order_items', 'discount_rate < 0', COUNT(*) FROM analytics.fact_order_items WHERE discount_rate < 0 UNION ALL SELECT 'analytics.fact_order_items', 'order_item_total < 0', COUNT(*) FROM analytics.fact_order_items WHERE order_item_total < 0 UNION ALL SELECT 'analytics.fact_order_items', 'late_delivery_risk NOT IN (0,1)', COUNT(*) FROM analytics.fact_order_items WHERE late_delivery_risk IS NOT NULL AND late_delivery_risk NOT IN (0,1) ORDER BY table_name, validation_check;
